(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["theory"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="th-batch-latency-slo"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉与它到底在算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-2\">二 · 为什么需要这个模型：三个决策它必须回答</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-3\">三 · 常见误解之一：把均值当目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-4\">四 · 常见误解之二：线性叠加在 chunked prefill 下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-5\">五 · 常见误解之三：prefix 复用命中后仍用旧 B*</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-6\">六 · 定义里必须写死的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-7\">七 · 批上界不是容量上限：线性叠加模型的适用边界与三类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-8\">八 · 批上界的边界：模型在哪里失效，代价落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-9\">九 · 预填项的两块时间：算力主导与带宽尾巴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-10\">十 · 解码项的分子结构：$B$ 为什么抬高单步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-11\">十一 · 线性叠加在哪一步成立、在哪一步破裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-12\">十二 · 对 $B$ 求极小的结构：为什么是 p99 而不是均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-13\">十三 · 边界条件下的项重估：prefix 命中与 KV 驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-14\">十四 · 公式的适用边界：线性叠加在哪里断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-15\">十五 · 批上界 B* 的适用边界：线性叠加在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-16\">十六 · 线性叠加假设的成立条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-17\">十七 · chunked prefill 下的耦合失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-18\">十八 · 排队项与尾部分布：公式只给路径时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-19\">十九 · 每步重读全 KV 的假设与驻留优化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-20\">二十 · 规模上限：批大小与上下文长度的双重天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-21\">二十一 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-22\">二十二 · 边界在哪里：线性叠加假设的失效条件与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-23\">二十三 · 从公式到决策变量：把 B 当作唯一可控旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-24\">二十四 · 定批大小：按 p99 求 B*，而不是按均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-25\">二十五 · 定并行度：N_active 与 B 的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-26\">二十六 · 定 KV 预算：把约束写进 B 的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-27\">二十七 · 定 SLO 与算例：反解可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-28\">二十八 · 三个必须校准的输入项与误用防线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-29\">二十九 · 批上界、并行度与 KV 预算：模型能定什么、定不了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-30\">三十 · 误用一：用均值时延调批，把 p99 交给运气</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-31\">三十一 · 误用二：chunked prefill 下仍按线性叠加估 TTFT</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-32\">三十二 · 误用三：prefix 复用命中后不下调 TPOT 带宽项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-33\">三十三 · 反例：一次把 B* 定错的完整推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-34\">三十四 · 把误用变成检查项：上线前的四个对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-35\">三十五 · 批上界的三类误用：均值陷阱、叠加幻觉与复用失算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-36\">三十六 · 误用诊断：从均值陷阱到耦合盲区</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:527px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 527.0 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：代码补全的 TTFT 与 TPOT 由预填计算量、解码步数与批内排…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\text{TTFT}\\approx\\frac{2N_{\\te…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：线性叠加假设忽略预填与解码在同一 SM 上的争抢；chunked …</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉与它到底在算什么</h3>\n<p>连续批调度的时延模型，一句话：<strong>把一次请求的端到端时延拆成“预填一次 + 解码 T<sub>out</sub> 次”，每次解码都要重读批内全部 KV 与权重，于是批越大单步越慢、但每请求摊到的固定开销越小，两条曲线交叉处就是 p99 时延最优的批上界 B<sup>*</sup>。</strong>这句话里藏着三个可被工程检验的断言：时延可加、批摊薄固定开销、存在极小点。本片段只做一件事——把这句直觉翻译成可写进容量规划文档的严格定义，并划清它不适用的边界。</p>\n<p>严格定义如下。设请求到达后进入调度器的等待队列，其端到端时延为</p>\n<div class=\"formula\">$$L = \\text{TTFT} + T_{\\text{out}}\\cdot\\text{TPOT}$$</div>\n<p>其中 TTFT 是首 token 时延，TPOT 是相邻输出 token 的平均间隔（time per output token）。模型进一步把两项展开为</p>\n<div class=\"formula\">$$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}},\\qquad \\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>第一项是预填的算力时间（系数 2 对应前向两次矩阵乘的量级，S<sub>in</sub> 为输入 token 数，仓库级上下文可达 10<sup>5</sup>），第二项是预填阶段把 KV 写进显存的带宽时间，τ<sub>queue</sub> 是调度排队时延。TPOT 的分子是“批内全部 KV + 权重”的字节数，B 越大分子越大。于是目标函数写成</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</div>\n<p>注意这里求的是 p99 而非均值——这是定义的一部分，不是修辞。B<sup>*</sup> 是一个<strong>统计量上的极小点</strong>，不是解析式上的驻点，因为 τ<sub>queue</sub> 的尾部分布由到达过程决定，闭式解通常不存在。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-2\">二 · 为什么需要这个模型：三个决策它必须回答</h3>\n<p>没有这个模型，工程上只能靠“调大 batch 提吞吐、调小 batch 保时延”的口号拍脑袋。有了它，三个具体决策才有依据。</p>\n<ul>\n<li><strong>批上界。</strong>代码补全的 T<sub>out</sub> 通常只有 32–256，端到端时延里 TTFT 占比高、TPOT 累计项相对小，因此 B 不能照搬离线吞吐场景的大批。模型给出的 B<sup>*</sup> 直接写进调度器的 max_num_seqs 上限。</li>\n<li><strong>预填与解码的解耦。</strong>仓库级上下文 S<sub>in</sub> 达 10<sup>5</sup> 时，TTFT 第一项随 S<sub>in</sub> 线性膨胀；若不做 chunked prefill，一次长预填会把整批解码卡住，TPOT 出现尖刺。模型把算力项与带宽项分开写，正是为了判断“该切块还是该排队”。</li>\n<li><strong>SLO 反推容量。</strong>给定 p99 TTFT 与 p99 TPOT 的 SLO，模型可反推单副本能承载的并发与到达率上限，这是容量规划里唯一能写成不等式的部分。</li>\n</ul>\n<p>代价必须说清楚：解这个模型要跑仿真或 M/G/1 近似，本身有计算成本；更重要的是，模型里的 π<sub>eff</sub> 与 β<sub>eff</sub> 是<strong>实测标定值</strong>，受 MMA 利用率与 attention 非线性影响，换精度（NVFP4 与 FP8）、换并行切分都要重标。举例：同一张 B200 上，FP8 与 NVFP4 的 β<sub>eff</sub> 不同，若沿用旧标定值算出的 B<sup>*</sup>，批上界会系统性偏移，表现为 p99 时延在压测中稳定超标而均值正常——这正是尾部被忽略的典型症状。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-3\">三 · 常见误解之一：把均值当目标</h3>\n<p>最常见的误用是只用均值时延调参。均值意义上的最优批往往远大于 p99 意义上的最优批，因为均值对尾部不敏感。突发到达（而非泊松）时，τ<sub>queue</sub> 的尾部被拉长，均值仍好看，p99 已经击穿补全 SLO。工程判断很直接：<strong>调度器的批上限应当由 p99 目标函数决定，均值只用于容量估算的粗筛。</strong>求解 p99 需要 M/G/1 近似或离散事件仿真，把到达过程的方差作为输入，而不是假设泊松。</p>\n<p>代价体现在两个方向：批定得过大，尾请求排队时间击穿 SLO；批定得过小，GPU 利用率与吞吐被无谓牺牲。二者都不是“调参手感”问题，而是目标函数选错。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-4\">四 · 常见误解之二：线性叠加在 chunked prefill 下失效</h3>\n<p>公式把 TTFT 与 TPOT 写成互不相干的两项，前提是预填与解码不在同一 SM 上争抢。chunked prefill 部署恰恰打破这个前提：预填块与解码步交织在同一批里，预填吃算力、解码吃带宽，二者在同一 SM 上交替，实际 TTFT 与 TPOT 存在耦合。此时仍按线性叠加估算 TTFT，预测与实测偏差会很大。</p>\n<p>具体机制：一个 chunk 的预填插入解码批后，该步的 TPOT 分子里多了 chunk 的激活与 KV 写入，单步时间被抬高；反过来，解码批占用 SM 也稀释了预填的 π<sub>eff</sub>。因此 chunked prefill 下必须<strong>实测校准</strong>，把耦合项作为修正因子写进模型，而不是继续用两项相加。代价是标定工作量增加，收益是长上下文场景下 TTFT 尖刺被削平——仓库级 10<sup>5</sup> token 的预填若不分块，解码批会被整段阻塞，TPOT 尾部直接失控。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-5\">五 · 常见误解之三：prefix 复用命中后仍用旧 B<sup>*</sup></h3>\n<p>TPOT 公式假设解码每步重读全部 KV。若采用 KV 分块驻留或 prefix 复用命中，被复用的前缀 KV 不再每步从显存重读，TPOT 的带宽项显著下降。此时若仍按未命中时的标定值求 B<sup>*</sup>，批上界定得过低，吞吐被白白牺牲。</p>\n<p>机制上，prefix 命中把 M<sub>KV</sub>(S) 中命中部分从分子里扣掉，等价于降低了单步的 β 压力，最优批随之上移。工程判断：<strong>B<sup>*</sup> 必须按“命中率分层”分别求解</strong>——高命中率的补全流量可以用更大批，低命中率的长上下文请求维持小批，调度器按请求的 prefix 命中状态路由到不同批池。代价是调度逻辑复杂度上升与批池碎片化，收益是同一副本上吞吐与时延同时改善。若不做分层而统一取小批，等于用吞吐换一个并不存在的时延收益。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-6\">六 · 定义里必须写死的适用边界</h3>\n<p>把边界写进定义，模型才可被审计。四条：其一，线性叠加假设忽略预填与解码在同一 SM 上的争抢，chunked prefill 下需实测校准；其二，公式只给单请求路径时延，不含排队论尾部分布，p99 须由 M/G/1 或仿真求得；其三，假设解码每步重读全 KV，KV 分块驻留或 prefix 复用命中会显著下调 TPOT 带宽项并使 B<sup>*</sup> 上移；其四，τ<sub>queue</sub> 依赖到达过程，泊松与突发的尾部分布形状不同，同一 B<sup>*</sup> 不可跨流量模式复用。</p>\n<p>一个具体例子收束：代码补全副本上，T<sub>out</sub> 取 128、S<sub>in</sub> 为常规函数上下文时，B<sup>*</sup> 由 TPOT 项主导，批上限偏小；同一副本若接入仓库级 10<sup>5</sup> token 的检索增强请求，TTFT 算力项主导，必须切 chunked prefill 并单独标定耦合因子，否则两个流量混跑时 p99 一定违约。模型的价值不在于给出一个数，而在于把“哪个流量、哪种命中状态、哪条到达过程”作为求解 B<sup>*</sup> 的必要输入写死在定义里。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-7\">七 · 批上界不是容量上限：线性叠加模型的适用边界与三类失效</h3>\n<p>把连续批调度的时延写成 TTFT 加输出步数乘 TPOT 的线性叠加，本质是一次<strong>路径分解</strong>：先假设一个请求的端到端时延等于“进入调度器到首 token”加上“每个解码步的固定成本乘以步数”，再对批大小 B 求 p99 极小值。这个分解成立的前提是预填与解码在时间上可分离、在资源上不重叠。一旦部署形态打破这两条，公式给出的 B* 就不再是可用结论，而只是一个需要校准的初值。具体地，第一项预填算力时间 $2N_{\\text{active}}S_{\\text{in}}/\\pi_{\\text{eff}}$ 随活跃请求数与输入长度线性增长，仓库级上下文 $S_{\\text{in}}$ 可达 $10^5$，这一项在长上下文补全里往往直接吃掉 TTFT 预算的大头；第二项 $M_{\\text{KV}}(S_{\\text{in}})/\\beta_{\\text{eff}}$ 是预填阶段把 KV 写入显存的带宽时间，它与算力项串行叠加的假设，在 chunked prefill 下并不成立。</p>\n<p>失效条件之一是<strong>预填与解码争抢同一组 SM</strong>。chunked prefill 把长预填切成若干块，与解码步交织在同一迭代里，此时预填的 MMA 占用会挤压解码的带宽窗口，TTFT 与 TPOT 不再是两个独立可加的项，而是通过 SM 占用率耦合。工程上的表现是：按线性模型算出的 TTFT 偏乐观，实测首 token 时延随 chunk 大小与并发解码请求数漂移。校准方法是把 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 视为随 chunk 配置变化的经验系数，用少量实测点回归，而不是当作硬件常数。失效条件之二是<strong>排队项 $\\tau_{\\text{queue}}$ 只给单请求路径时延</strong>：公式里它是一个标量，但真实到达过程是泊松或突发的，尾部分布必须用 M/G/1 近似或离散事件仿真求得，否则 p99 无从谈起。失效条件之三是<strong>解码每步重读全 KV 的假设</strong>：一旦启用 KV 分块驻留或 prefix 复用命中，TPOT 的带宽项 $M_{\\text{KV}}(S)B/\\beta_{\\text{eff}}$ 显著下降，B* 随之上移，此时仍按原公式定批上界会白白牺牲吞吐。</p>\n<p>把三类失效放在一起看，可以得到一个工程判断表：</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>模型哪一项失真</th><th>后果</th><th>应对</th></tr></thead><tbody><tr><td>纯连续批处理、短输入</td><td>基本可用</td><td>B* 接近实测最优</td><td>按 p99 求解即可</td></tr><tr><td>chunked prefill 交织</td><td>TTFT 算力项偏乐观</td><td>首 token SLO 违约</td><td>实测校准 $\\pi_{\\text{eff}}$，解耦预填块</td></tr><tr><td>突发到达</td><td>$\\tau_{\\text{queue}}$ 无尾部</td><td>p99 击穿补全 SLO</td><td>M/G/1 或仿真求尾部分布</td></tr><tr><td>prefix 复用命中</td><td>TPOT 带宽项偏高</td><td>B* 定得过低、吞吐浪费</td><td>下调带宽项后重解 B*</td></tr></tbody></table>\n<p>代价侧的直觉是：批越大，每请求分摊的权重读取与调度固定开销越小，但单步要重读批内全部 KV，$\\text{TPOT}\\approx(M_{\\text{KV}}(S)B+M_{\\text{weights}})/\\beta_{\\text{eff}}$ 的分子随 B 线性上升，于是单步变慢、输出 token 的交付节奏变粗。对代码补全这种 $T_{\\text{out}}$ 仅 32–256 的短输出场景，端到端时延里 TPOT 乘步数的占比不高，TTFT 与排队项才是 p99 的主导，因此低延迟补全应取较小 B 保尾部；而仓库级长上下文预填则应靠 chunked prefill 把 TTFT 的算力项与带宽项解耦，避免一次长预填把整批解码阻塞。换句话说，B* 是 SLO 的函数而非硬件的函数：同一个集群，补全流与长上下文流应使用不同的批上界，混跑时必须按流量比例加权求解 p99，而不是取一个全局常数。</p>\n<p>最常见的误用是只按均值时延调 B，均值下排队项被摊薄得很漂亮，突发到达时 $\\tau_{\\text{queue}}$ 的尾部却直接击穿补全 SLO；第二类误用是在 chunked prefill 部署里继续用线性叠加估 TTFT，预测与实测偏差大却归因于“硬件波动”；第三类误用是 prefix 复用命中后没有下调 TPOT 带宽项，把 B* 定得过低，用吞吐换来了并不存在的时延收益。判断一个批上界是否可信，看它是否同时标注了到达过程假设、是否区分了预填与解码的资源重叠、以及是否在命中复用后重新求解。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-8\">八 · 批上界的边界：模型在哪里失效，代价落在哪里</h3>\n<p>这套时延模型的价值不在给出一个可套用的 B 值，而在明确它的适用域：单请求路径时延可加、解码每步重读全 KV、预填与解码不争抢同一组 SM。三条同时成立时，<span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span> 才有意义；任一条被打破，交点位置就会偏移，按公式定的批上界要么保守浪费吞吐，要么激进击穿 SLO。代码补全的 T_out 只有 32–256，端到端时延里 TTFT 占比高，因此 B 的可行区间天然偏小；仓库级上下文 S_in 可达 10^5，预填项 2N_active·S_in/π_eff 会直接吃掉大部分时延预算，此时批大小的调节余地被预填挤压。</p>\n<p>第一个失效条件是线性叠加本身。chunked prefill 把长预填切成块与解码步交织，预填的算力项与解码的带宽项在同一 SM 上争抢，TTFT 与 TPOT 不再是独立相加的两段，而是通过 SM 占用率耦合。工程上的代价是预测偏差：按叠加式估出的 TTFT 偏乐观，实际 p99 被预填块拖长，补全首字延迟超出 SLO。校准手段只能是实测扫描 chunk 大小与并发组合，把耦合项作为修正因子回填，而不是继续信任解析式。</p>\n<p>第二个失效条件是 τ_queue 的分布假设。公式只描述单请求路径时延，排队项依赖到达过程——泊松到达与突发到达的尾部行为完全不同，均值相同的两种到达在 p99 上可差出一个量级。因此 B* 必须用 M/G/1 近似或离散事件仿真求 p99，而不是对均值时延求极小。只按均值调参是典型误用：均值达标、突发时排队时延击穿补全 SLO，且这种违约在平稳流量下不可见。</p>\n<p>第三个失效条件在 KV 驻留侧。模型假设解码每步重读批内全部 KV，TPOT 分子含 M_KV(S)·B；一旦 prefix 复用命中或 KV 分块驻留生效，带宽项显著下降，TPOT 随 B 上升的斜率变缓，B* 应上移。若沿用未修正的公式，会把批上界定得过低，用吞吐换取并不存在的时延收益。下表给出三种部署形态下模型可信度的快速判断。</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>模型可用性</th><th>主要代价</th></tr></thead><tbody><tr><td>纯解码、无 chunked prefill、无复用</td><td>可作一阶估算，B* 需 p99 校准</td><td>均值调参导致尾部违约</td></tr><tr><td>chunked prefill 交织</td><td>线性叠加失效，需实测修正</td><td>TTFT 预测偏乐观，首字超 SLO</td></tr><tr><td>prefix 复用 / KV 分块驻留</td><td>带宽项需下调，B* 上移</td><td>批上界过低，吞吐无谓牺牲</td></tr></tbody></table>\n<h3 id=\"th-batch-latency-slo-sec-9\">九 · 预填项的两块时间：算力主导与带宽尾巴</h3>\n<p>TTFT 公式的第一项 $\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$ 常被误读成“一个系数乘 token 数除以算力”。系数 2 来自前向两遍矩阵乘（QKV 投影与输出投影各一次 GEMM 语义），$N_{\\text{active}}$ 是当前活跃请求数——注意它不是批大小 $B$，而是“此刻真正在预填的请求数”，在 chunked prefill 下它可能远小于 $B$。$\\pi_{\\text{eff}}$ 不是峰值 FLOPS，而是扣掉 MMA 利用率与 attention 非线性开销后的有效算力：attention 的 $O(S_{\\text{in}}^2)$ 部分不走 tcgen05 的大 MMA 形状，利用率天然低于线性层，所以 $\\pi_{\\text{eff}}$ 随 $S_{\\text{in}}$ 增长而下降，这一项对长上下文是超线性的。仓库级 $S_{\\text{in}}$ 可达 $10^5$，此时算力项是绝对主项，第二项 $\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}$ 只是把刚算出的 KV 写回 HBM 的带宽尾巴，量级上通常被第一项吞掉——但它是解耦点：chunked prefill 把 $S_{\\text{in}}$ 切成块后，每块的算力项线性缩小，而 KV 写入按块摊开，二者不再串行叠加，这正是后面要讲的耦合来源。</p>\n<p>推导关键步在于把“预填”当成一个不可中断的整体。若不做 chunk，一个 $10^5$ token 的仓库级请求会把整块 SM 占满数百毫秒量级，期间所有解码步被阻塞，$\\tau_{\\text{queue}}$ 对同批其他请求爆炸。所以第一项的工程含义不是“算得快”，而是“这块算力占用能否被切片”。代价侧：预填是算力密集、功耗高的阶段，B200 上大 MMA 打满时功耗接近封装上限，而解码阶段是带宽密集、功耗低得多；同一 SM 上两种负载交替，功耗与热节流会反过来压低 $\\pi_{\\text{eff}}$，这是公式里没写但实测必须校准的项。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-10\">十 · 解码项的分子结构：$B$ 为什么抬高单步</h3>\n<p>TPOT 公式 $\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$ 的分子有两块：批内全部 KV 的重读量与权重读取量。关键在 $M_{\\text{KV}}(S)$ 里的 $S$ 是“当前序列长度”，随解码步增长，所以同一请求的 TPOT 在生成过程中是单调上升的——代码补全 $T_{\\text{out}}$ 只有 32–256，这个上升幅度有限，但仓库级上下文下 $S$ 起点就是 $10^5$，$M_{\\text{KV}}$ 基数极大，$B$ 稍微一抬分子就爆。$M_{\\text{weights}}$ 是固定项，与 $B$ 无关，这正是连续批处理的收益来源：$B$ 增大时每请求分摊的权重读取下降，摊薄效应在 $B$ 小时最明显，随 $B$ 增大边际递减。而 KV 项随 $B$ 线性增长，两条曲线一个降一个升，交点附近就是吞吐最优，但不是 p99 最优。</p>\n<p>这里有个容易漏掉的推导细节：$\\beta_{\\text{eff}}$ 不是 HBM 峰值带宽，而是解码阶段实际能达到的有效带宽。解码每步是“读权重 + 读 KV + 写一个 token 的 KV”，读占绝对主导，写可以忽略；但权重读取在 $B$ 大时会与 KV 读取争抢 HBM 通道，且 KV 的访问模式（按 head 分块、跨请求不连续）比权重的顺序流式访问效率低，所以 $\\beta_{\\text{eff}}$ 随 $B$ 增大而轻微下降。公式把它当常数是近似，真实系统里分子涨得比线性更快一点，这使 $B^{*}$ 比纯线性模型预测的更靠左。工程代价：解码阶段是纯带宽瓶颈，SM 算力大量闲置，功耗低但 HBM 通道饱和，此时再增加 $B$ 只增加时延不增加有用算力。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-11\">十一 · 线性叠加在哪一步成立、在哪一步破裂</h3>\n<p>端到端时延写成 $\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$ 这一步，隐含假设是预填与解码在时间上串行、在资源上不重叠。非 chunk 部署下这基本成立：预填跑完才进解码。但 chunked prefill 把预填切块后，块与解码步在同一 SM 上交织，预填块会挤占解码步的带宽与算力，实际 TPOT 在预填块插入的那几步会尖峰化。公式给出的 TPOT 是“稳态解码步”的时延，不含这些尖峰，所以按公式算出的 p99 会系统性偏低。校准办法不是改公式，而是把 $\\beta_{\\text{eff}}$ 拆成“纯解码带宽”和“被预填块占用后的有效带宽”两个实测值，按 chunk 占空比加权——这是离散化近似所在：连续时间的资源争抢被压成一个平均占空比系数。</p>\n<p>第二个破裂点是 $\\tau_{\\text{queue}}$。公式把它写成单请求路径上的一个加项，但排队时延本质是分布量，不是标量。到达过程若是泊松，$\\tau_{\\text{queue}}$ 的尾部按 M/G/1 的 Pollaczek–Khinchine 形式随利用率非线性发散；若是突发到达（代码补全的真实形态：开发者连续敲键触发多次补全），尾部比泊松更重。所以 $B^{*}=\\arg\\min_B \\text{p99}(\\cdot)$ 里的 p99 不能由公式解析求出，只能靠 M/G/1 近似或离散事件仿真。离散化近似在这里体现为：把连续到达流切成调度 tick，每个 tick 内按当前 $B$ 组批，tick 粒度决定了排队时延的量化误差——tick 太粗，小请求被无谓等待；tick 太细，组批开销吃掉摊薄收益。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-12\">十二 · 对 $B$ 求极小的结构：为什么是 p99 而不是均值</h3>\n<p>把 $B$ 当连续变量看，$\\text{TTFT}$ 里的 $\\tau_{\\text{queue}}(B)$ 随 $B$ 增大而下降（批越大，单请求等待组批的时间占比越小、调度次数越少），$T_{\\text{out}}\\cdot\\text{TPOT}(B)$ 随 $B$ 增大而上升（分子线性涨）。均值意义下两者交点给出一个温和的 $B$；但 p99 意义下，$\\tau_{\\text{queue}}$ 的尾部随 $B$ 下降得更快（大 $B$ 把突发吸收进批里），而 TPOT 的尾部随 $B$ 上升得更陡（$B$ 大时任何一次 KV 重读抖动都被放大到整批）。两条尾部曲线的交点比均值交点更靠左，这就是“低延迟补全应取较小 $B$ 保 p99”的数学来源。代码补全 $T_{\\text{out}}$ 只有 32–256，TPOT 项被 $T_{\\text{out}}$ 放大得不多，所以 $B^{*}$ 主要由 TTFT 的排队尾部决定——换句话说，补全场景的批上界是排队主导，不是解码带宽主导。</p>\n<div class=\"formula\">$$\\frac{\\partial}{\\partial B}\\Big[\\text{p99}\\big(\\tau_{\\text{queue}}(B)\\big)+T_{\\text{out}}\\cdot\\text{p99}\\big(\\text{TPOT}(B)\\big)\\Big]=0$$</div>\n<p>这个隐式方程说明 $B^{*}$ 是“排队尾部下降速率”与“解码尾部上升速率”之比等于 $T_{\\text{out}}$ 的点。工程判断：$T_{\\text{out}}$ 越大（长生成任务），TPOT 项权重越高，$B^{*}$ 越靠左；$T_{\\text{out}}$ 小（补全），$B^{*}$ 可以放宽但仍受排队尾部约束。代价侧要盯住的是：$B$ 过大时 p99 TPOT 抬升会直接击穿补全 SLO，而 $B$ 过小时权重读取摊薄不足、吞吐浪费，两者都是可观测的。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-13\">十三 · 边界条件下的项重估：prefix 命中与 KV 驻留</h3>\n<p>公式假设解码每步重读全部 KV。一旦 prefix 复用命中（同一仓库文件的公共前缀被缓存），$M_{\\text{KV}}(S)$ 里被命中的部分不再需要从 HBM 重读——它们已在更快的层级或已被复用，TPOT 带宽项显著下降。此时若仍按原公式定 $B^{*}$，会把批上界定得过低，白白牺牲吞吐。同理，KV 分块驻留（把热 KV 块留在片上或近存）也压低 $\\beta_{\\text{eff}}$ 的有效分子。修正方式是在 $M_{\\text{KV}}(S)$ 上乘一个命中折扣因子，折扣因子由实测命中率给出，$B^{*}$ 随折扣增大而上移。这是“失效条件”里最容易被忽略的一条，因为命中率是运行时统计量，不是静态配置。</p>\n<p>另一个边界是预填与解码争抢 SM。非 chunk 下预填独占，公式成立；chunk 下 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 都变成占空比的函数，TTFT 的算力项与 TPOT 的带宽项通过 SM 占用率耦合。此时线性叠加给出的 TTFT 是乐观下界，实测偏差随 chunk 占空比增大。工程上应把 chunk 大小作为独立调参维度：chunk 越小，TTFT 越平滑但组批开销越高；chunk 越大，预填块对解码步的尖峰越明显。仓库级 $10^5$ 上下文下，chunk 大小直接决定 TTFT 的算力项能否被切片到与解码步同量级，这是把公式从“估算”变成“可校准模型”的关键动作。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-14\">十四 · 公式的适用边界：线性叠加在哪里断裂</h3>\n<p>把端到端时延写成 <span class=\"formula\">$$\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$$</span> 再对批大小 <span class=\"formula\">$$B$$</span> 求极小，这个推导之所以能给出闭式直觉，全靠一个隐含前提：预填阶段与解码阶段互不干扰，各自独占一份资源。真实部署里这条前提最先断裂。预填的算力项 <span class=\"formula\">$$\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$$</span> 与解码的带宽项 <span class=\"formula\">$$\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 争抢的是同一批 SM：当 chunked prefill 把长预填切成小块插入解码步之间，二者在同一时间片上交织，预填吃掉的 MMA 周期直接压低了解码可用的有效带宽 <span class=\"formula\">$$\\beta_{\\text{eff}}$$</span>，反过来解码驻留的 KV 又挤占了预填可用的片上容量。此时 TTFT 与 TPOT 不再是两个独立可加的项，而是通过共享的 SM 占用率耦合在一起。工程含义很直接：在 chunked prefill 部署中按线性叠加估出的 TTFT 会系统性偏乐观，实测与预测的偏差随 chunk 粒度变细而放大，必须用实测校准系数替换公式里的 <span class=\"formula\">$$\\pi_{\\text{eff}}$$</span> 与 <span class=\"formula\">$$\\beta_{\\text{eff}}$$</span>，而不是照搬静态值。</p>\n<p>第二个断裂点是 <span class=\"formula\">$$\\tau_{\\text{queue}}$$</span>。公式只描述单请求沿路径的时延，排队项被当成一个可加常数，但真实到达过程是泊松或突发——代码补全的请求往往跟着编辑节奏成簇到达，突发窗口内排队时延的尾部远厚于均值。要拿到 <span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span> 里的 p99，必须用 M/G/1 近似或离散事件仿真求出排队时延的尾部分布，再与路径时延卷积；直接把均值 <span class=\"formula\">$$\\tau_{\\text{queue}}$$</span> 代进去求出的 <span class=\"formula\">$$B^{*}$$</span> 会偏大，因为均值掩盖了突发下的长尾。这正是最常见的误用：只按均值时延调批大小，突发到达下排队时延击穿补全 SLO，而调参者看到的平均指标一切正常。</p>\n<p>第三个断裂点藏在解码带宽项的分母假设里：公式默认每个解码步重读批内全部 KV。一旦启用 KV 分块驻留或 prefix 复用命中，命中部分的 KV 不再从 HBM 重读，<span class=\"formula\">$$M_{\\text{KV}}(S)$$</span> 实际参与带宽计算的部分显著下降，TPOT 的带宽项随之收缩，<span class=\"formula\">$$B^{*}$$</span> 应当上移。若命中后仍按原式估算，会把批上界定得过低，用无谓的吞吐牺牲换取并不存在的时延收益。下表把三类失效条件与对应的修正动作并列，便于在调参时逐条核对。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式中被破坏的假设</th><th>系统代价表现</th><th>修正动作</th></tr></thead><tbody><tr><td>chunked prefill 交织</td><td>TTFT 与 TPOT 可加、资源独占</td><td>TTFT 预测偏乐观，实测偏差随 chunk 变细放大</td><td>实测校准 <span class=\"formula\">$$\\pi_{\\text{eff}}$$</span>、<span class=\"formula\">$$\\beta_{\\text{eff}}$$</span></td></tr><tr><td>突发到达</td><td><span class=\"formula\">$$\\tau_{\\text{queue}}$$</span> 为常数、无尾分布</td><td>p99 击穿 SLO，均值指标正常</td><td>M/G/1 或仿真求尾部，按 p99 求 <span class=\"formula\">$$B^{*}$$</span></td></tr><tr><td>prefix 复用命中</td><td>每步重读全 KV</td><td><span class=\"formula\">$$B^{*}$$</span> 偏低，吞吐被无谓牺牲</td><td>下调 TPOT 带宽项后重解 <span class=\"formula\">$$B^{*}$$</span></td></tr></tbody></table>\n<p>把这三条放在一起看，公式的真正用途不是给出一个可直接部署的 <span class=\"formula\">$$B$$</span> 值，而是给出各项的相对量级与单调方向：<span class=\"formula\">$$S_{\\text{in}}$$</span> 从常规上下文涨到仓库级 <span class=\"formula\">$$10^5$$</span> 时，预填算力项主导 TTFT，此时应配合 chunked prefill 把算力项与带宽项解耦，避免长预填阻塞解码；而 <span class=\"formula\">$$T_{\\text{out}}$$</span> 落在 32–256 的低延迟补全区间时，TPOT 被乘上输出步数后权重上升，批上界必须压小以保 p99。换句话说，<span class=\"formula\">$$B^{*}$$</span> 是随 <span class=\"formula\">$$S_{\\text{in}}$$</span>、<span class=\"formula\">$$T_{\\text{out}}$$</span> 与命中率漂移的曲面，任何把它当固定常数的调参都是在用均值思维替代尾部思维。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-15\">十五 · 批上界 B* 的适用边界：线性叠加在哪里失效</h3>\n<p>该模型的可信区间由三条假设划出。第一，TTFT 与 TPOT 被当作可加的两段，但预填与解码共享同一批 SM 的 MMA 与 TMEM 资源；一旦启用 chunked prefill，预填块被切碎插入解码步之间，二者在同一时间片上争抢算力，实际 TTFT 会随同批解码请求数上升，TPOT 也会因预填块插入而出现尖峰。此时 <span>TTFT + T_out·TPOT</span> 不再是两个独立项的相加，而是耦合函数，B* 必须用实测曲线而非解析式求解。第二，公式只描述单请求的路径时延，τ_queue 的尾部由到达过程决定：泊松到达下 M/G/1 的等待时间分布重尾，突发到达（仓库级补全常见的一次性大批量触发）下尾部更厚，p99 只能靠仿真或排队论近似取得，用均值代入会系统性低估 B*。第三，解码每步重读全 KV 的假设在 KV 分块驻留或 prefix 复用命中后不成立——命中前缀的 KV 不再重读，TPOT 的带宽项按命中比例下降，B* 随之上移；若仍按未命中公式定批，吞吐被无谓牺牲。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效场景</th><th>系统代价</th></tr></thead><tbody><tr><td>预填/解码线性叠加</td><td>chunked prefill 交织</td><td>TTFT 预测偏低，p99 违约</td></tr><tr><td>τ_queue 仅均值</td><td>突发到达</td><td>尾部排队击穿补全 SLO</td></tr><tr><td>每步重读全 KV</td><td>prefix 复用命中</td><td>B* 过低，吞吐损失</td></tr></tbody></table>\n<p>工程上的处理是把公式降级为标定骨架而非预测器：先用小批实测 π_eff 与 β_eff（含 MMA 利用率与 attention 非线性带来的折损），再在目标到达过程下扫 B 取 p99 曲线的最小点。对 T_out 仅 32–256 的补全请求，TPOT 项权重小，B* 主要由 τ_queue 与预填算力项决定，宜取小批保尾部；对 S_in 达 10^5 的仓库级上下文，则应让 chunked prefill 把预填的算力项与带宽项解耦，避免长预填阻塞解码队列，此时 B* 的求解必须把预填块占用的 SM 时间显式计入分母。</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}(B)+T_{\\text{out}}\\cdot\\text{TPOT}(B)\\right),\\quad \\text{TPOT}(B)\\approx\\frac{(1-h)\\,M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>式中 h 为 prefix 命中比例，是原公式未含的修正项；h 上升使 TPOT 斜率变缓，最优点右移。反过来，若部署中预填与解码争抢严重，TTFT(B) 随 B 增长快于线性，最优点左移。两类偏移方向相反，说明 B* 不是硬编码常数，而是随部署形态（是否 chunked、命中率高低、到达是否突发）漂移的运行参数，需按 SLO 定期重标定。</p>\n<h3 id=\"th-batch-latency-slo-sec-16\">十六 · 线性叠加假设的成立条件</h3>\n<p>公式把端到端时延写成 <span class=\"formula-inline\">TTFT + T_out·TPOT</span> 的线性叠加，这一步在工程上等价于声明：预填阶段与解码阶段在时间上互斥、在资源上不重叠。成立条件比多数人以为的苛刻——预填的最后一批 token 完成 KV 写入之后，解码步才开始读这份 KV；解码期间没有新的预填请求插入同一组 SM；两个阶段各自独占 <span class=\"formula-inline\">π_eff</span> 与 <span class=\"formula-inline\">β_eff</span> 这两个有效效率常数，且这两个常数与批大小无关。第三条最容易被忽略：<span class=\"formula-inline\">π_eff</span> 受 MMA 利用率与 attention 非线性影响，<span class=\"formula-inline\">β_eff</span> 受 HBM 访问模式与 KV 布局影响，二者在批大小跨过某个阈值后都会漂移，此时对 <span class=\"formula-inline\">B</span> 求极小得到的 <span class=\"formula-inline\">B*</span> 只是在局部常数假设下的驻点，不是全局最优。</p>\n<p>一个具体机制能说明这条边界：在非 chunked 的朴素连续批处理里，调度器把预填请求作为不可分割的整体提交，预填期间解码请求被整体挂起，线性叠加成立；一旦预填请求的 <span class=\"formula-inline\">S_in</span> 达到仓库级 <span class=\"formula-inline\">10^5</span> 量级，调度器不可能让整批解码停等这么久，于是必然切分，假设随之破裂。工程判断是：当 <span class=\"formula-inline\">2N_active·S_in/π_eff</span> 这一项与 <span class=\"formula-inline\">T_out·TPOT</span> 同量级或更大时，线性叠加已经不可用，必须换用耦合模型或直接实测标定。代价层面，误用线性叠加的直接后果是 TTFT 预测偏低、<span class=\"formula-inline\">B*</span> 定得偏大，p99 在突发到达下击穿补全 SLO。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-17\">十七 · chunked prefill 下的耦合失效</h3>\n<p>chunked prefill 把长预填切成若干块，与解码步在同一 SM 上交织执行，这正是线性叠加失效的典型场景。交织带来的耦合有两层：其一，每个解码步的 <span class=\"formula-inline\">TPOT</span> 不再只由 <span class=\"formula-inline\">M_KV(S)·B + M_weights</span> 决定，还要加上同周期内预填块占用的算力与带宽份额；其二，预填块被拉长后，<span class=\"formula-inline\">TTFT</span> 的第一项不再是单次 <span class=\"formula-inline\">2N_active·S_in/π_eff</span>，而是被解码步反复打断后的有效算力时间，实际值高于公式给出的理想值。</p>\n<p>伪代码层面的判据可以写成：设预填块占用的 SM 周期比例为 <span class=\"formula-inline\">ρ_p</span>，则交织期的解码有效带宽近似退化为 <span class=\"formula-inline\">β_eff·(1-ρ_p)</span>，代入 TPOT 得</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{interleaved}}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}\\,(1-\\rho_p)}$$</div>\n<p>该式表明 <span class=\"formula-inline\">ρ_p</span> 越大，<span class=\"formula-inline\">B*</span> 越向小值移动，因为每步的固定成本被预填抬高了。具体例子：仓库级上下文 <span class=\"formula-inline\">S_in=10^5</span>、补全 <span class=\"formula-inline\">T_out</span> 取 32–256 的下沿时，若按线性叠加把 <span class=\"formula-inline\">B</span> 调到吞吐最优，实测 p99 会因 <span class=\"formula-inline\">ρ_p</span> 的周期性尖峰而明显高于预测；正确做法是把 <span class=\"formula-inline\">ρ_p</span> 作为调度器的可调旋钮，与 <span class=\"formula-inline\">B</span> 联合标定，而不是先定 <span class=\"formula-inline\">B</span> 再谈预填策略。代价是标定工作量上升，收益是 TTFT 与 TPOT 的预测偏差收敛到可接受范围。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-18\">十八 · 排队项与尾部分布：公式只给路径时延</h3>\n<p><span class=\"formula-inline\">τ_queue</span> 在公式里是一个标量，但真实系统中它是随机变量，其分布由到达过程决定。公式本身只描述单请求的路径时延，不含排队论的尾部分布；把 <span class=\"formula-inline\">τ_queue</span> 取均值代入 <span class=\"formula-inline\">B*</span> 的求解，等价于用均值时延调参，这是最常见的误用。代码补全的到达过程既非严格泊松也非平稳：IDE 侧的触发具有突发性，同一仓库的多个文件可能在秒级窗口内集中请求，此时排队时延的尾部远厚于泊松假设。</p>\n<p>求解 p99 需要 M/G/1 近似或离散事件仿真。M/G/1 的等待时间尾部分布依赖服务时间分布的前两阶矩，而本模型的服务时间（一次预填加若干解码步）方差很大——<span class=\"formula-inline\">S_in</span> 从数百到 <span class=\"formula-inline\">10^5</span> 跨越三个数量级，<span class=\"formula-inline\">T_out</span> 在 32–256 间波动，因此 Pollaczek–Khinchine 型近似只能给出量级判断，不能替代仿真。工程上的可行路径是：用仿真或在线采样得到 <span class=\"formula-inline\">p99(TTFT + T_out·TPOT)</span> 关于 <span class=\"formula-inline\">B</span> 的曲线，再取极小；公式的作用退化为给出曲线形状的先验（<span class=\"formula-inline\">B</span> 增大时排队项单调降、TPOT 项单调升），缩小搜索区间。代价是仿真基础设施的投入，以及在线采样带来的可观测性开销；不做这一步的代价则是突发到达下 SLO 违约，且违约不可预测。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-19\">十九 · 每步重读全 KV 的假设与驻留优化</h3>\n<p>TPOT 公式的分子 <span class=\"formula-inline\">M_KV(S)·B + M_weights</span> 建立在“解码每步重读批内全部 KV”之上。这条假设在标准 paged KV 布局下成立，但在两类优化下失效：KV 分块驻留（把热 KV 块固定在近端存储层级，减少每步的重读量）与 prefix 复用命中（共享前缀的 KV 只读一次或按命中率折算）。失效后 <span class=\"formula-inline\">M_KV(S)</span> 的有效值下降，TPOT 的带宽项显著变小，<span class=\"formula-inline\">B*</span> 随之上移——因为单步变便宜了，可以容纳更大的批而不牺牲 p99。</p>\n<p>量化这条边界的判据是命中率 <span class=\"formula-inline\">h</span>：有效 KV 读取量近似为 <span class=\"formula-inline\">(1-h)·M_KV(S)·B</span>，代入得</p>\n<div class=\"formula\">$$\\text{TPOT}_{h}\\approx\\frac{(1-h)\\,M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>常见误用正是忽略这个 <span class=\"formula-inline\">(1-h)</span> 因子：prefix 复用已经上线、命中率可观，却仍按未命中的 TPOT 估 <span class=\"formula-inline\">B*</span>，结果批上界定得过低，吞吐被无谓牺牲。具体例子：同一仓库的连续补全请求共享大量文件级前缀，命中后每步 KV 读取量下降，若仍沿用旧 <span class=\"formula-inline\">B*</span>，解码步的带宽远未打满，GPU 在低利用率下空转。工程判断是：把 <span class=\"formula-inline\">h</span> 纳入 <span class=\"formula-inline\">B*</span> 的在线重估回路，命中率变化时同步上调批上界，而不是把 <span class=\"formula-inline\">B*</span> 当作静态配置。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-20\">二十 · 规模上限：批大小与上下文长度的双重天花板</h3>\n<p>模型在规模上有两条硬边界。第一条是批大小的天花板：<span class=\"formula-inline\">B</span> 增大到 <span class=\"formula-inline\">M_KV(S)·B</span> 主导分子后，TPOT 随 <span class=\"formula-inline\">B</span> 线性上升，而排队项的下降是次线性的，<span class=\"formula-inline\">B*</span> 之后继续加批只会拉高 p99；更硬的约束来自 KV 显存容量，超出并发容量后调度器被迫抢占或换出，此时公式里的 <span class=\"formula-inline\">B</span> 已不是有效批大小，模型失效。第二条是上下文长度的天花板：<span class=\"formula-inline\">S_in</span> 达到 <span class=\"formula-inline\">10^5</span> 时，预填算力项与 KV 写入带宽项同时膨胀，<span class=\"formula-inline\">π_eff</span> 因 attention 非线性而进一步下降，公式中两个常数假设同时漂移。</p>\n<p>两条边界交汇处是模型最不可靠的区域：大批加长上下文，预填与解码争抢同一组 SM，<span class=\"formula-inline\">π_eff</span> 与 <span class=\"formula-inline\">β_eff</span> 都无法当作常数。此时的工程做法不是继续解析求解，而是退化为约束优化：把 <span class=\"formula-inline\">B</span> 的上界交给显存容量与抢占策略决定，把 <span class=\"formula-inline\">S_in</span> 的上界交给 chunked prefill 的块大小决定，公式只用于在可行域内做粗筛。代价是失去了闭式最优解，收益是避免了在模型失效区做出错误的容量规划。可观测的判据是：当实测 <span class=\"formula-inline\">π_eff</span> 相对标定值漂移超过可接受带宽，或 <span class=\"formula-inline\">β_eff</span> 随 <span class=\"formula-inline\">B</span> 呈系统性下降，就应判定已越过适用边界，切换到实测驱动的调度参数搜索。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-21\">二十一 · 失效条件的工程清单</h3>\n<p>把上述边界收敛成一张可执行的检查表，用于在部署前判定公式是否仍可作为决策依据。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>假设</th><th>失效触发条件</th><th>后果</th><th>替代手段</th></tr>\n</thead>\n<tbody>\n<tr><td>预填与解码时间互斥</td><td>启用 chunked prefill，<span class=\"formula-inline\">ρ_p</span> 不可忽略</td><td>TTFT 低估、TPOT 低估</td><td>耦合模型加实测标定</td></tr>\n<tr><td><span class=\"formula-inline\">π_eff</span>、<span class=\"formula-inline\">β_eff</span> 与 <span class=\"formula-inline\">B</span> 无关</td><td>批大小或 <span class=\"formula-inline\">S_in</span> 跨过阈值</td><td><span class=\"formula-inline\">B*</span> 偏离全局最优</td><td>分段标定效率常数</td></tr>\n<tr><td><span class=\"formula-inline\">τ_queue</span> 为标量均值</td><td>突发到达、非平稳负载</td><td>p99 违约不可预测</td><td>M/G/1 近似或仿真</td></tr>\n<tr><td>解码每步重读全 KV</td><td>KV 分块驻留、prefix 复用命中</td><td><span class=\"formula-inline\">B*</span> 定得过低、吞吐浪费</td><td>引入命中率 <span class=\"formula-inline\">h</span> 重估</td></tr>\n<tr><td>批大小可自由增大</td><td>触及 KV 显存容量、发生抢占换出</td><td>有效批失真、模型失效</td><td>显存约束下的可行域搜索</td></tr>\n</tbody>\n</table>\n<p>清单的使用方式是逐条打勾：任一条触发即意味着该部署场景下 <span class=\"formula-inline\">B*</span> 的解析解只能作为初值，最终值必须由实测 p99 曲线确定。代价是每次部署变更（上下文长度档位、prefix 命中率、chunk 块大小）都要重跑标定，收益是把 SLO 违约从“事后发现”变成“事前可判”。对于代码补全这类 <span class=\"formula-inline\">T_out</span> 仅 32–256 的低延迟场景，p99 对 <span class=\"formula-inline\">B</span> 的敏感度高于均值，清单中排队项与驻留项两条应优先核对；对于仓库级长上下文预填，耦合项与规模上限两条是主要风险源。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-22\">二十二 · 边界在哪里：线性叠加假设的失效条件与规模上限</h3>\n<p>这套时延模型能被工程直接使用，靠的是一个很强的结构性假设：端到端时延可以写成 <span class=\"sym\">TTFT</span> 与 <span class=\"sym\">T<sub>out</sub></span>·<span class=\"sym\">TPOT</span> 的线性叠加，且两项各自独立可估。代码补全场景里，<span class=\"sym\">T<sub>out</sub></span> 通常只有 32–256 个 token，输出项权重不大，模型的精度主要押在 <span class=\"sym\">TTFT</span> 上；而 <span class=\"sym\">TTFT</span> 的第一项 <span class=\"sym\">2N<sub>active</sub>S<sub>in</sub>/π<sub>eff</sub></span> 在仓库级上下文（<span class=\"sym\">S<sub>in</sub></span> 可达 10<sup>5</sup>）下会膨胀到主导地位。一旦预填与解码不再是时间上分离的两个阶段，这个叠加就不再成立——chunked prefill 把长预填切成若干块插入解码步之间，预填的算力项与解码的带宽项在同一 SM 上争抢执行资源，<span class=\"sym\">TTFT</span> 被拉长、<span class=\"sym\">TPOT</span> 被抬高，二者出现耦合。此时公式给出的两个数只是“无争抢”的理想下界，实测偏差随 chunk 粒度与批内预填比例上升。工程判断是：只要部署启用了 chunked prefill，就必须用实测校准系数替换 <span class=\"sym\">π<sub>eff</sub></span> 与 <span class=\"sym\">β<sub>eff</sub></span>，不能直接套用解析式。</p>\n<p>第二个失效点是排队项 <span class=\"sym\">τ<sub>queue</sub></span> 的分布性质。公式只描述单请求的路径时延，把 <span class=\"sym\">τ<sub>queue</sub></span> 当作一个可加的标量；但真实到达过程是泊松或突发的，排队时延是随机变量而非常数。要求 <span class=\"sym\">B<sup>*</sup></span> 就必须求 p99，而 p99 无法从单请求路径时延解析得到，需借助 M/G/1 近似或离散事件仿真。常见误用正是只按均值时延调批大小：均值下 <span class=\"sym\">B</span> 可以取得较大以摊薄固定开销，但突发到达时尾部排队时延击穿补全 SLO，p99 违约而均值指标仍然漂亮。规模上限也在这里显形——当 <span class=\"sym\">S<sub>in</sub></span> 达到 10<sup>5</sup> 量级、并发请求数上升时，预填算力项本身已接近单步预算，任何排队抖动都会被放大成数量级的尾延迟，模型退化为只能给出下界。</p>\n<p>第三个失效点来自 KV 驻留策略对 <span class=\"sym\">TPOT</span> 带宽项的改写。模型假设解码每步重读批内全部 KV，即 <span class=\"sym\">M<sub>KV</sub>(S)·B</span> 随 <span class=\"sym\">B</span> 线性增长；若启用 KV 分块驻留或 prefix 复用命中，命中部分的 KV 不再每步从 HBM 重读，<span class=\"sym\">TPOT</span> 的带宽项显著下降，最优批随之上移。反过来，prefix 复用命中后若仍按原带宽项估 <span class=\"sym\">TPOT</span>，会把 <span class=\"sym\">B<sup>*</sup></span> 定得过低，用吞吐换来了并不存在的时延收益。下表给出三类边界下模型的可用性判断：</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>模型状态</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>预填/解码时间分离</td><td>线性叠加成立</td><td>—</td><td>可直接用解析式定 <span class=\"sym\">B<sup>*</sup></span></td></tr><tr><td>chunked prefill 交织</td><td>两项耦合，解析式仅给下界</td><td>TTFT 拉长、TPOT 抬高，SM 争抢</td><td>实测校准 <span class=\"sym\">π<sub>eff</sub></span>、<span class=\"sym\">β<sub>eff</sub></span></td></tr><tr><td>prefix 复用命中</td><td>带宽项高估</td><td><span class=\"sym\">B<sup>*</sup></span> 偏低，吞吐被牺牲</td><td>下调 <span class=\"sym\">M<sub>KV</sub></span> 后重解</td></tr></tbody></table>\n<p>把边界收束成一句可执行的判据：当 <span class=\"sym\">S<sub>in</sub></span> 处于 10<sup>5</sup> 量级且部署启用 chunked prefill 时，<span class=\"sym\">TTFT</span> 的算力项与带宽项必须解耦估计，并把预填块对解码步的挤占作为独立惩罚项加入 <span class=\"sym\">TPOT</span>，否则 <span class=\"sym\">B<sup>*</sup></span> 的求解只是在优化一个不存在的系统；而当 <span class=\"sym\">T<sub>out</sub></span> 停留在 32–256 的补全区间、KV 复用命中率稳定时，带宽项应随命中率下调，让 <span class=\"sym\">B<sup>*</sup></span> 上移以释放吞吐——这两条判据的取舍点不在公式内部，而在部署形态是否破坏了“预填与解码不共享执行资源”这一前提。</p>\n<h3 id=\"th-batch-latency-slo-sec-23\">二十三 · 从公式到决策变量：把 B 当作唯一可控旋钮</h3>\n<p>在容量决策里，TTFT 与 TPOT 两条式子不是用来“解释现象”的，而是用来解出四个待定量的：批上界 <em>B</em>、并行度 <em>N</em><sub>active</sub>、KV 预算、以及 SLO 的可行域。做法是把端到端时延写成 <em>D</em>(<em>B</em>) = TTFT + <em>T</em><sub>out</sub>·TPOT，其中只有 <em>B</em> 出现在 TPOT 的分子里、同时通过 τ<sub>queue</sub> 反向出现在 TTFT 里。于是决策变成一次单变量求极小，其余三个量都由 <em>B</em><sup>*</sup> 反推。</p>\n<p>具体机制上，连续批处理每步重读批内全部 KV，TPOT 的分子 <em>M</em><sub>KV</sub>(<em>S</em>)·<em>B</em> + <em>M</em><sub>weights</sub> 随 <em>B</em> 线性增长，而每请求摊到的固定开销（权重读取、kernel 启动）按 1/<em>B</em> 衰减。前者是抬升项，后者是摊薄项，两者相抵的位置就是吞吐-时延的拐点。注意 <em>M</em><sub>weights</sub> 不随 <em>B</em> 变，所以当 <em>B</em> 大到 <em>M</em><sub>KV</sub>·<em>B</em> 远超权重项时，TPOT 近似正比于 <em>B</em>——这就是“批越大单步越慢”的定量来源，也是 <em>B</em><sup>*</sup> 存在的根本原因。</p>\n<p>系统代价上，<em>B</em> 的每一次上调都在用 TPOT 换吞吐：解码阶段的带宽占用从 <em>M</em><sub>weights</sub>/β<sub>eff</sub> 抬到 (<em>M</em><sub>KV</sub>·<em>B</em>+<em>M</em><sub>weights</sub>)/β<sub>eff</sub>，单步墙钟时间同比上升，而总吞吐（token/s）大致按 <em>B</em>/TPOT 变化，只有分子中权重项占比仍显著时才单调增。举例：代码补全 <em>T</em><sub>out</sub> 取 128，若把 <em>B</em> 从 8 翻到 32，TPOT 的 KV 项翻四倍，端到端时延中 128·TPOT 这一项直接主导 <em>D</em>，p99 立刻被推高——这正是低延迟补全必须压小 <em>B</em> 的原因。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-24\">二十四 · 定批大小：按 p99 求 B*，而不是按均值</h3>\n<p>求 <em>B</em><sup>*</sup> 的正确做法是对 p99 分位数求极小，而非对均值。均值下 τ<sub>queue</sub> 被平滑掉，<em>B</em> 会一路推到吞吐拐点；但补全 SLO 通常卡在 p99，突发到达时排队项会击穿预算。工程上的可执行流程是：固定 <em>S</em><sub>in</sub>、<em>T</em><sub>out</sub> 的分布，对候选 <em>B</em> 网格做离散扫描，每个 <em>B</em> 用 M/G/1 近似或事件仿真得到 τ<sub>queue</sub> 的 p99，再代入 <em>D</em>(<em>B</em>) 取最小。</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right),\\qquad \\text{s.t.}\\;\\; B\\cdot M_{\\text{KV}}(S)\\le M_{\\text{KV,budget}}$$</div>\n<p>伪代码思路：对每个 <em>B</em>，先用 TPOT 式子算单步时间，再以到达率 λ 与单步服务时间构造 M/G/1 的等待时间分布取 p99 作为 τ<sub>queue</sub>，累加得 <em>D</em><sub>p99</sub>(<em>B</em>)；扫描区间上界由 KV 预算约束截断（见第四节）。这一步的代价是仿真开销，但只做一次离线标定，之后按负载档位查表。</p>\n<p>具体例子：仓库级上下文 <em>S</em><sub>in</sub> 达 10<sup>5</sup> 量级时，预填算力项 2<em>N</em><sub>active</sub><em>S</em><sub>in</sub>/π<sub>eff</sub> 本身就吃掉大部分 TTFT 预算，此时 <em>B</em><sup>*</sup> 被 TTFT 侧钉死在小值，继续加批只会让 TPOT 项在 128 步上放大 128 倍地恶化 p99。反过来，<em>T</em><sub>out</sub> 只有 32 的短补全，<em>T</em><sub>out</sub>·TPOT 权重低，<em>B</em><sup>*</sup> 可以明显上移——同一套公式，两个 <em>T</em><sub>out</sub> 档位给出完全不同的批上界，这就是“按场景定批”而非“全局一个批”的依据。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-25\">二十五 · 定并行度：N_active 与 B 的耦合约束</h3>\n<p>并行度 <em>N</em><sub>active</sub> 只出现在 TTFT 的第一项，看似与 <em>B</em> 独立，实则被同一条 SM 资源约束耦合：预填与解码争抢同一批 SM，<em>N</em><sub>active</sub> 越大，预填算力项越小但占用越多 SM，留给解码的带宽与算力被压缩，TPOT 的 β<sub>eff</sub> 实际下降。因此定并行度不能只看 TTFT，要把 β<sub>eff</sub> 作为 <em>N</em><sub>active</sub> 的函数一起标定。</p>\n<p>机制上，预填是算力受限（π<sub>eff</sub> 受 MMA 利用率与 attention 非线性影响），解码是带宽受限（β<sub>eff</sub>），两类负载对 SM 的占用形态不同。把 <em>N</em><sub>active</sub> 调大等价于把更多 SM 划给算力密集的预填，解码侧的有效带宽随之被稀释。工程判断是：先在纯解码工况下标定 β<sub>eff</sub>(<em>N</em><sub>active</sub>) 曲线，再回到 TTFT 式子选 <em>N</em><sub>active</sub>，使 2<em>N</em><sub>active</sub><em>S</em><sub>in</sub>/π<sub>eff</sub> 落入 TTFT 预算的预定份额（例如给排队与 KV 写入留出余量）。</p>\n<p>代价面：<em>N</em><sub>active</sub> 提升换来 TTFT 下降，但以解码 β<sub>eff</sub> 下降为代价，等价于把 TPOT 抬高、把 <em>B</em><sup>*</sup> 往下压。所以并行度与批大小不是两个独立旋钮，而是一条权衡曲线上的两个坐标；容量规划时应把它们作为一对 (<em>N</em><sub>active</sub>, <em>B</em><sup>*</sup>) 联合标定，而不是分别取“最大值”。长上下文场景下这条曲线尤其陡：<em>S</em><sub>in</sub>=10<sup>5</sup> 时预填项对 <em>N</em><sub>active</sub> 极其敏感，稍加并行就能把 TTFT 拉回预算内，代价是解码侧可用的 β<sub>eff</sub> 明显缩水。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-26\">二十六 · 定 KV 预算：把约束写进 B 的可行域</h3>\n<p>KV 预算是 <em>B</em><sup>*</sup> 搜索区间的硬上界：<em>B</em>·<em>M</em><sub>KV</sub>(<em>S</em>) ≤ <em>M</em><sub>KV,budget</sub>。这一步把显存容量公式（本模块另有专条，此处只引用结论）转成批大小的可行域边界。注意 <em>M</em><sub>KV</sub>(<em>S</em>) 随上下文长度增长，所以同一个 KV 预算在不同 <em>S</em> 档位下给出完全不同的 <em>B</em> 上限——仓库级上下文把 <em>B</em> 上限压得很低，短上下文则宽松。</p>\n<p>机制上，KV 预算的分配要在“批大小上限”与“上下文长度上限”之间做二维取舍：给定总显存，<em>B</em>·<em>S</em> 近似受同一容量约束，扩大 <em>S</em> 就必然压缩 <em>B</em>。工程做法是把预算切成三段：权重常驻、KV 池、以及为 chunked prefill 的中间激活留的余量。KV 池一旦定死，<em>B</em><sup>*</sup> 的搜索上界随之确定，若公式解出的最优批超出该上界，说明瓶颈已从时延转到显存，此时应下调 <em>S</em> 上限或引入 KV 分块驻留，而不是硬扛。</p>\n<p>代价面：KV 预算收紧直接压低并发容量，进而抬高 τ<sub>queue</sub> 的 p99，形成“显存→排队→SLO”的传导链。具体例子：<em>S</em><sub>in</sub>=10<sup>5</sup> 的仓库级请求，单请求 KV 占用极大，KV 池只允许很小的 <em>B</em>，此时 <em>B</em><sup>*</sup> 由显存而非时延决定；而 <em>T</em><sub>out</sub>=32 的短补全、<em>S</em><sub>in</sub> 仅数千 token 时，KV 池能容纳大得多的 <em>B</em>，<em>B</em><sup>*</sup> 回到时延主导区间。两类请求混跑时，应按 <em>S</em> 分池或分队列，否则长上下文请求会把短请求的 <em>B</em> 上限一起拖低。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-27\">二十七 · 定 SLO 与算例：反解可行域</h3>\n<p>定 SLO 是把上述过程反过来：给定 p99 预算 <em>D</em><sub>SLO</sub>，问是否存在 (<em>B</em>, <em>N</em><sub>active</sub>) 使 p99(<em>D</em>) ≤ <em>D</em><sub>SLO</sub>。由于 <em>D</em> 对 <em>B</em> 是“先降后升”的凸形，可行域是 <em>B</em> 轴上的一个区间 [<em>B</em><sub>min</sub>, <em>B</em><sub>max</sub>]，而非单点。区间为空即 SLO 不可达，需要放宽 <em>T</em><sub>out</sub>、拆分上下文长度档位，或引入 chunked prefill 解耦预填与解码。</p>\n<p>算例（定性数值关系，不引入实验数据）：设某补全档位 <em>T</em><sub>out</sub>=128，TTFT 预算与总 p99 预算已定。取 <em>B</em>=8 时 TPOT 较小、τ<sub>queue</sub> 的 p99 因并发不足而偏高；取 <em>B</em>=32 时 τ<sub>queue</sub> 下降但 TPOT 的 KV 项约翻四倍，128·TPOT 项反超，总 p99 上升。扫描网格上 <em>D</em><sub>p99</sub>(<em>B</em>) 呈 U 形，谷底即 <em>B</em><sup>*</sup>；把 <em>D</em><sub>SLO</sub> 画一条水平线，与 U 形曲线的两个交点就是 [<em>B</em><sub>min</sub>, <em>B</em><sub>max</sub>]。若 <em>D</em><sub>SLO</sub> 低于谷底，则该档位在现有 <em>N</em><sub>active</sub> 与 KV 预算下不可行。</p>\n<p>这个算例的工程含义是：SLO 不该写成“平均时延 ≤ X”，而应写成“在给定 <em>S</em>、<em>T</em><sub>out</sub> 分布下 p99 ≤ X，且存在非空批区间”。容量规划的输出因此是三张表——每个上下文档位的 <em>B</em><sup>*</sup>、对应的 <em>N</em><sub>active</sub>、以及该档位下 SLO 是否可达——而不是一个全局批大小。低延迟补全档取区间下沿保 p99，吞吐优先档取谷底附近；两者不能共用同一 <em>B</em>。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-28\">二十八 · 三个必须校准的输入项与误用防线</h3>\n<p>公式能用的前提是 π<sub>eff</sub>、β<sub>eff</sub>、τ<sub>queue</sub> 三个量经过实测校准，否则解出的 <em>B</em><sup>*</sup> 只是纸面最优。π<sub>eff</sub> 受 MMA 利用率与 attention 非线性影响，长 <em>S</em><sub>in</sub> 下衰减明显；β<sub>eff</sub> 随 <em>N</em><sub>active</sub> 与 KV 驻留策略变化；τ<sub>queue</sub> 依赖到达过程是泊松还是突发，突发到达下 p99 远高于泊松假设。三者都必须按档位标定，不能全负载共用一个常数。</p>\n<p>三条误用防线对应三种失效模式。其一，只按均值调 <em>B</em>：均值把 τ<sub>queue</sub> 的尾部抹平，<em>B</em> 被推到过大，突发到达时 p99 击穿补全 SLO——防线是任何调参都以 p99 为目标函数。其二，chunked prefill 部署下仍按线性叠加估 TTFT：预填与解码在同一 SM 上交织争抢，TTFT 与 TPOT 存在耦合，线性叠加会系统性低估，防线是用实测校准替代解析式，或把预填份额作为显式参数引入。其三，prefix 复用命中后未下调 TPOT 的带宽项：命中使每步重读的 KV 显著减少，TPOT 分子下降，<em>B</em><sup>*</sup> 本应上移，若仍按未命中标定就会把批定得过低、无谓牺牲吞吐——防线是在 <em>M</em><sub>KV</sub>(<em>S</em>) 中按命中率折算有效 KV 读取量，并随命中率变化重解 <em>B</em><sup>*</sup>。</p>\n<p>最后落在一条工程判断上：<em>B</em><sup>*</sup> 不是一次性常数，而是随 <em>S</em> 档位、<em>T</em><sub>out</sub> 分布、prefix 命中率、以及 <em>N</em><sub>active</sub> 配置漂移的量。把 <em>B</em><sup>*</sup> 做成在线可调的查表项——输入是当前上下文中位数与命中率，输出是批上界——比把它写死进部署配置更稳；而每次 KV 驻留策略或并行度变更，都必须重跑一次 p99 扫描，否则公式给出的最优点已经不在当前系统上。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-29\">二十九 · 批上界、并行度与 KV 预算：模型能定什么、定不了什么</h3>\n<p>这个模型在容量决策里能直接回答三类问题，且只回答这三类。第一，<strong>定批上界</strong>：把 $B^{*}=\\arg\\min_{B}\\mathrm{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})$ 当作连续批处理的调度上限，而不是当作吞吐最优批。代码补全的 $T_{\\text{out}}$ 落在 32–256，端到端时延里 TPOT 项被乘了 32–256 次，因此 $B$ 的边际代价被放大数十倍——同样把 $B$ 从 8 抬到 32，对话类负载可能只多几毫秒，补全负载的 p99 会成倍恶化。第二，<strong>定并行度</strong>：$\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 是并行切分的函数，TP 增大使 $\\beta_{\\text{eff}}$ 上升但每卡权重份额下降、通信占比上升，PP 增大则引入流水气泡抬高 $\\tau_{\\text{queue}}$ 的等效值；把实测的 $\\pi_{\\text{eff}},\\beta_{\\text{eff}}$ 代回公式，可以判断某组 TP/PP 组合是否真的把 $B^{*}$ 推高了，而不是凭“卡多就快”拍板。第三，<strong>定 KV 预算</strong>：$M_{\\text{KV}}(S_{\\text{in}})$ 与 $M_{\\text{KV}}(S)$ 同时出现在 TTFT 的带宽项和 TPOT 的分子里，KV 预算不是“能塞多少塞多少”，而是要让常驻 KV 在 $\\beta_{\\text{eff}}$ 下重读一遍的时间不击穿 TPOT 目标，剩余空间才留给批宽度。</p>\n<p>算例按量纲走，不引具体实测值。设某仓库级补全请求 $S_{\\text{in}}=10^{5}$、$T_{\\text{out}}=128$，SLO 要求 p99 端到端不超过一个补全可接受的量级。预填项 $\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$ 随活跃请求数线性增长，是 TTFT 的主项；此时若把 $B$ 调大以摊薄固定开销，TPOT 分子里的 $M_{\\text{KV}}(S)B$ 同步变大，$128\\times\\text{TPOT}$ 迅速吃掉时延预算。工程上的做法是先把 $B$ 压到只够维持 $\\beta_{\\text{eff}}$ 饱和的下界，再用 chunked prefill 把 $10^{5}$ 量级的预填切成块，使预填算力项与 KV 写入带宽项解耦，避免一次长预填把整批解码请求的 TPOT 顶穿。反过来，若 prefix 复用命中率高，$M_{\\text{KV}}(S)$ 的有效重读量下降，TPOT 带宽项随之收缩，此时应把 $B^{*}$ 上移——沿用未命中时的 $B$ 是把吞吐白白让给时延。</p>\n<p>边界必须写清楚，否则这套公式会被当成万能估算器。线性叠加 $\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$ 的前提是预填与解码不共享 SM；chunked prefill 部署下二者在同一 SM 上交织争抢，实测 TTFT 与 TPOT 存在耦合，公式给出的两个数只能作为下界参考，必须用实测校准系数。$\\tau_{\\text{queue}}$ 只刻画单请求路径时延，不含排队论尾部分布：到达过程是泊松还是突发，决定 p99 与均值的偏离幅度，$B^{*}$ 必须用 M/G/1 近似或离散事件仿真求解，不能对均值时延求极小。还有一条隐含假设——解码每步重读全部 KV；一旦采用 KV 分块驻留或 prefix 复用，TPOT 的带宽项显著下降，$B^{*}$ 会上移，此时不修正模型就会把批上界定得过低。</p>\n<table class=\"mini\"><thead><tr><th>决策对象</th><th>模型给出的量</th><th>失效时的系统代价</th></tr></thead><tbody><tr><td>批上界 $B$</td><td>$B^{*}$（按 p99 求极小）</td><td>按均值调参 → 突发到达下排队击穿补全 SLO</td></tr><tr><td>并行度 TP/PP</td><td>$\\pi_{\\text{eff}},\\beta_{\\text{eff}}$ 代入后的 $B^{*}$ 走向</td><td>忽略通信与气泡 → $\\tau_{\\text{queue}}$ 被低估，TTFT 预测偏乐观</td></tr><tr><td>KV 预算</td><td>$M_{\\text{KV}}(S)$ 的重读时间</td><td>预算给满 → TPOT 带宽项抬高，$T_{\\text{out}}$ 放大后违约</td></tr><tr><td>chunked prefill 块长</td><td>预填项与带宽项的解耦程度</td><td>仍按线性叠加估 TTFT → 实测与预测偏差大</td></tr></tbody></table>\n<p>三种误用对应三种可观测的代价。只按均值时延调 $B$，在突发到达下 $\\tau_{\\text{queue}}$ 的尾部把 p99 推过 SLO，表现为“平均很快、用户偶尔卡死”；在 chunked prefill 部署里继续用线性叠加估 TTFT，预填与解码争抢 SM 的耦合被忽略，容量规划按预测值配卡，上线后 TTFT 系统性偏高；prefix 复用命中后不下调 TPOT 带宽项，$B^{*}$ 定得过低，GPU 在 $\\beta_{\\text{eff}}$ 未饱和的状态下空转，吞吐被无谓牺牲。判断这套模型是否仍然可信，看一个信号即可：把实测 p99 与模型预测的比值按 $B$ 分档画出来，若比值随 $B$ 单调漂移，说明线性叠加已失效，应切换到仿真驱动的批上界搜索，而不是继续在解析式上微调参数。</p>\n<h3 id=\"th-batch-latency-slo-sec-30\">三十 · 误用一：用均值时延调批，把 p99 交给运气</h3>\n<p>最常见的误用是把 <span class=\"sym\">B</span> 的选取建立在对 <span class=\"formula\">$$\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$$</span> 求均值再最小化的基础上，而不是对 p99 求最小。均值最优化在数学上完全合法，但它优化的对象错了：代码补全的 SLO 通常写在尾部，例如“p99 端到端不超过某阈值”，而均值最优点与 p99 最优点在突发到达下并不重合。机制上，均值把 <span class=\"sym\">τ_queue</span> 压成一个标量，等于假设到达过程平滑；一旦到达是突发的，排队时延的分布有长尾，均值最优点会把 <span class=\"sym\">B</span> 推到偏大一侧，因为大 <span class=\"sym\">B</span> 摊薄了每请求固定开销、均值好看，但每个解码步要重读的 KV 更多，单步时间抬高，尾部请求在队列里等得更久。</p>\n<p>识别方法很直接：把线上同一时段的 <span class=\"sym\">B</span>、实测 TTFT 分布与 TPOT 分布拉出来，若均值 TTFT 稳定而 p99 TTFT 随 <span class=\"sym\">B</span> 上升而恶化，说明调参目标选错了。系统代价体现在两个方向：<span class=\"sym\">B</span> 偏大时单步带宽时间按 <span class=\"formula\">$$\\frac{M_{\\text{KV}}(S)\\,B}{\\beta_{\\text{eff}}}$$</span> 线性增长，尾部请求的 TPOT 被拉长；<span class=\"sym\">B</span> 偏小时固定开销 <span class=\"formula\">$$\\frac{M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 摊不薄，吞吐掉下去而 p99 未必改善。举例：仓库级补全 <span class=\"sym\">S_in</span> 到 10^5、<span class=\"sym\">T_out</span> 在 32–256 之间，若按均值把 <span class=\"sym\">B</span> 定在较大值，突发到达时新请求的 <span class=\"sym\">τ_queue</span> 被前面的大批解码步拖长，p99 端到端击穿 SLO，而均值报表一切正常——这正是“均值合规、尾部违约”的典型形态。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-31\">三十一 · 误用二：chunked prefill 下仍按线性叠加估 TTFT</h3>\n<p>线性叠加假设预填与解码互不干扰，各自占用独立的算力与带宽预算。chunked prefill 恰恰打破这个假设：预填被切成块，与解码步在同一 SM 上交织执行，预填的 MMA 占用与解码的 KV 重读共享同一份 <span class=\"sym\">β_eff</span> 与同一批 SM 周期。此时 <span class=\"formula\">$$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}}$$</span> 里的 <span class=\"sym\">π_eff</span> 与 <span class=\"sym\">β_eff</span> 不再是常数，而是随同批解码请求数 <span class=\"sym\">B</span> 变化的耦合量：解码请求越多，预填块能拿到的算力份额越少，第一项被系统性低估。</p>\n<p>后果是容量规划失真：按线性叠加算出的 TTFT 偏乐观，运维据此放大 <span class=\"sym\">B</span> 或收紧副本数，实测 p99 TTFT 却显著高于预测，SLO 在长上下文场景首先崩。识别信号是“预测-实测偏差随 <span class=\"sym\">S_in</span> 增大而增大”——短输入时预填块小、争抢弱，偏差不明显；<span class=\"sym\">S_in</span> 到 10^5 时预填块本身就很重，与解码争抢 SM 的效应被放大。校准手段不是改公式系数，而是把 <span class=\"sym\">π_eff</span>、<span class=\"sym\">β_eff</span> 写成 <span class=\"sym\">B</span> 与 chunk 大小的函数，用实测拟合，再把拟合结果代回 <span class=\"sym\">B*</span> 的搜索。系统代价是双重的：预填块切得太细，解码步被频繁打断、TPOT 抖动；切得太粗，预填独占 SM 时间长，解码请求的 <span class=\"sym\">τ_queue</span> 抬升。这个权衡必须靠实测校准，公式只能给出结构，不能给出数值。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-32\">三十二 · 误用三：prefix 复用命中后不下调 TPOT 带宽项</h3>\n<p>公式的推导前提是“解码每步重读批内全部 KV”。prefix 复用命中后，被复用的前缀 KV 常驻且不再每步重算重读，<span class=\"formula\">$$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 的分子实际小于按全量 <span class=\"sym\">M_KV(S)</span> 估算的值。若部署中已经启用前缀缓存却仍按全量 KV 代入公式求 <span class=\"sym\">B*</span>，得到的 <span class=\"sym\">B*</span> 会偏低——因为模型“以为”每步很贵，于是把批压小，牺牲了本可摊薄的吞吐。</p>\n<p>机制上，命中率决定有效 KV 重读量：命中比例越高，TPOT 对 <span class=\"sym\">B</span> 的敏感度越低，<span class=\"sym\">B*</span> 越应上移。识别方法是做一次对照：固定 <span class=\"sym\">B</span>，分别在有、无 prefix 复用的两组请求上测 TPOT，若实测 TPOT 明显低于按全量 KV 的预测值，说明公式的带宽项需要按命中率折减。系统代价是吞吐被无谓牺牲：<span class=\"sym\">B</span> 定得过低，权重读取的固定开销 <span class=\"formula\">$$\\frac{M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 摊不薄，GPU 带宽利用率上不去，单位 token 成本抬高。举例：同一仓库的连续补全请求共享大量前缀，命中后每步只需重读增量 KV，此时把 <span class=\"sym\">B</span> 从按全量 KV 算出的值上调，可在 p99 不变的前提下显著提升吞吐——但前提是先把 TPOT 公式的分子改成“未命中 KV + 命中增量”，否则上调 <span class=\"sym\">B</span> 只是盲目冒险。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-33\">三十三 · 反例：一次把 B* 定错的完整推演</h3>\n<p>设某代码补全服务，<span class=\"sym\">S_in</span> 主体在 10^5 量级（仓库级上下文），<span class=\"sym\">T_out</span> 取 128，SLO 为 p99 端到端不超过给定阈值。团队按线性叠加公式估算：预填算力项与 KV 写入项相加得 TTFT 预测，再用 <span class=\"formula\">$$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 对 <span class=\"sym\">B</span> 求均值最优，得到一个偏大的 <span class=\"sym\">B</span>，理由是“大批摊薄固定开销、均值吞吐最好”。上线后两个问题同时出现：其一，chunked prefill 已启用，预填块与解码争抢 SM，实测 TTFT 高于预测，且 <span class=\"sym\">S_in</span> 越长偏差越大；其二，突发到达时 <span class=\"sym\">τ_queue</span> 的长尾把 p99 端到端推过 SLO，而均值报表仍显示达标。</p>\n<p>正确的推演顺序应是：先用实测校准 <span class=\"sym\">π_eff</span>、<span class=\"sym\">β_eff</span> 随 <span class=\"sym\">B</span> 的耦合关系；再按 prefix 命中率折减 TPOT 分子；最后用 M/G/1 或仿真求 p99 端到端分布，对 <span class=\"sym\">B</span> 搜索 <span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span>。这个反例的教训不是“公式错了”，而是公式的三个前提——线性叠加、全量 KV 重读、均值可代表尾部——在真实部署里同时不成立时，<span class=\"sym\">B*</span> 会被推向错误方向。识别这类错误的通用判据是：预测与实测的偏差是否随 <span class=\"sym\">S_in</span>、<span class=\"sym\">B</span>、突发强度三者之一单调增大；若是，先怀疑前提失效，再怀疑参数标定。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-34\">三十四 · 把误用变成检查项：上线前的四个对照</h3>\n<p>把上述误用固化成上线前的对照实验，比事后调参便宜得多。第一，均值对照：同一 <span class=\"sym\">B</span> 下比较均值与 p99 端到端，若两者随 <span class=\"sym\">B</span> 的变化方向不一致，说明尾部主导，<span class=\"sym\">B*</span> 必须按 p99 求。第二，预填对照：固定 <span class=\"sym\">B</span>，扫 <span class=\"sym\">S_in</span> 从短到 10^5，看 TTFT 预测偏差是否随 <span class=\"sym\">S_in</span> 增大，若是则 chunked prefill 的耦合未被建模。第三，命中对照：开、关 prefix 复用各测一组 TPOT，按实测比值折减带宽项后再求 <span class=\"sym\">B*</span>。第四，突发对照：用泊松与突发两种到达过程各跑一遍仿真，比较两种到达下 p99 最优的 <span class=\"sym\">B</span> 是否一致；不一致说明 <span class=\"sym\">τ_queue</span> 的尾部分布不能省略。</p>\n<p>这四项对照的系统代价都很低——每组只需固定 <span class=\"sym\">B</span> 扫一个维度，不需要全网格搜索——但它们能挡住三类高频误用。真正昂贵的是误用上线后的代价：<span class=\"sym\">B</span> 偏大时尾部违约触发告警与回滚，<span class=\"sym\">B</span> 偏小时吞吐浪费直接体现为单位 token 成本。工程判断上，宁可把 <span class=\"sym\">B*</span> 的搜索做成带前提校验的流程，也不要把公式当成黑箱直接代参数：公式给的是结构，前提给的是适用域，两者缺一，<span class=\"sym\">B*</span> 就只是一个看起来精确的错误答案。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-35\">三十五 · 批上界的三类误用：均值陷阱、叠加幻觉与复用失算</h3>\n<p>这套时延模型最容易被误用的地方，不是公式本身写错，而是把它的三个前提当成无条件成立。第一个前提是 p99 可解：$B^{*}=\\arg\\min_{B}\\ \\text{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})$ 要求排队时延 $\\tau_{\\text{queue}}$ 的尾部分布已知，而 $\\tau_{\\text{queue}}$ 由到达过程决定——代码补全的请求到达既非严格泊松，也常在保存文件、切换分支、批量重构时突发成簇。工程上常见的做法是拿一段时间的均值时延曲线扫 $B$，取均值最低点当 $B^{*}$，结果在突发窗口里排队项被放大数倍，p99 端到端时延击穿补全 SLO。识别方法很直接：把同一 $B$ 下的时延分布按到达率分桶画出来，若均值曲线平缓而高分位曲线在某一 $B$ 之后陡升，说明 $B^{*}$ 已被均值掩盖；此时应改用 M/G/1 近似或离散事件仿真求尾部分布，而不是继续用均值扫参。代价是显性的——为压 p99 而把 $B$ 调小，解码步摊薄不足，每请求固定开销占比上升，吞吐下降；但若不调，突发时违约的补全请求会成片超时，重试又进一步抬高到达率，形成正反馈。</p>\n<p>第二个误用出现在 chunked prefill 部署里：仍按 $\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}}$ 做线性叠加估算。这个式子的隐含假设是预填与解码互不干扰，各自占用独立的算力与带宽预算；但在同一 SM 上二者交织执行，chunked prefill 把长预填切成小块插入解码步之间，预填的 MMA 占用会挤占解码步的带宽窗口，解码的 KV 重读又反过来拉长预填分块的有效算力时间。结果是实测 TTFT 系统性高于预测，且偏差随 $S_{\\text{in}}$ 增大而扩大——仓库级上下文 $S_{\\text{in}}$ 可达 $10^5$，此时预填算力项本就占主导，争抢带来的耦合误差足以让按公式选出的 $B$ 偏离真实最优。识别信号是：同一 $B$ 下把 chunk size 调小，若 TTFT 不降反升或 TPOT 同步恶化，说明耦合已经显著，公式的加法结构失效。此时应把 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 视为随 chunk 配置变化的实测标定量，用一组 chunk size 扫描做校准，而不是沿用离线测得的固定值。</p>\n<p>第三个误用与 prefix 复用有关。TPOT 公式 $\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$ 假设解码每步重读批内全部 KV；一旦 prefix 复用命中，被复用的前缀 KV 可驻留或分块复用，实际重读量显著低于 $M_{\\text{KV}}(S)\\cdot B$，带宽项下降，$B^{*}$ 理应上移。若部署中已开启 prefix 缓存却仍按未命中情形定 $B$，批上界被压在过低位置，解码步摊薄不足，吞吐被无谓牺牲——这是三个误用里唯一“保守反而吃亏”的情形。识别方法是统计命中率与实测 TPOT 的比值：命中率上升而 TPOT 未按预期下降，说明带宽项没被正确下调；反之若 TPOT 明显低于公式预测而 $B$ 未上调，就是 $B^{*}$ 定低的直接证据。修正时把 $\\beta_{\\text{eff}}$ 的有效分母按命中比例折算，重新解 $B^{*}$，并注意复用命中率本身随批内请求的上下文相似度变化，$B$ 增大可能降低平均命中率，二者需联合扫描而非单向调参。</p>\n<p>三类误用共享同一个工程判断：这套模型的输出是<strong>批上界的初值</strong>，不是可以直接下发的配置。它把 TTFT 拆成预填算力、KV 写入与排队三项，把 TPOT 拆成 KV 重读与权重读取两项，价值在于指出每一项随 $B$、$S_{\\text{in}}$、$T_{\\text{out}}$ 的走向，从而给出“往哪个方向调”的信号；但 $\\pi_{\\text{eff}}$、$\\beta_{\\text{eff}}$、$\\tau_{\\text{queue}}$ 的尾部分布、以及 chunked prefill 与 prefix 复用带来的耦合，都必须在目标部署上实测标定。一个可操作的反例是：某代码补全服务按均值扫参把 $B$ 定在较大值，仓库级长上下文请求突发时排队项击穿 p99，同时 chunked prefill 的争抢使实测 TTFT 高于预测，运维误以为是模型算错而继续加大 $B$ 摊薄开销，结果 TPOT 与 TTFT 同步恶化；正确动作是先用仿真求尾部分布定 $B$ 的上界，再按 chunk 配置校准 $\\pi_{\\text{eff}}$，最后按 prefix 命中率下调 TPOT 带宽项，三步都做完才谈得上把 $B^{*}$ 落到配置里。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-36\">三十六 · 误用诊断：从均值陷阱到耦合盲区</h3>\n<p>最常见的误用是把 <span class=\"sym\">B</span> 调到均值时延最低的点，而不是按 <span class=\"sym\">\\(B^{*}=\\arg\\min_{B}\\;\\text{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})\\)</span> 求解。均值最优的批往往偏大：因为 <span class=\"sym\">τ_queue</span> 的尾部在突发到达下呈非线性抬升，均值项被大量小排队样本稀释，而 p99 已被少数长排队请求击穿。识别方法很直接——在同一 <span class=\"sym\">B</span> 下同时记录均值与 p99 的 TTFT，若两者比值随 <span class=\"sym\">B</span> 增大而扩大，说明批已越过 p99 拐点。代价是吞吐指标好看、SLO 违约率上升：代码补全 <span class=\"sym\">\\(T_{\\text{out}}\\)</span> 仅 32–256，端到端时延里 TPOT 项占比小，p99 几乎完全由 <span class=\"sym\">τ_queue</span> 尾部决定，此时把 <span class=\"sym\">B</span> 按均值推到上限，等于用补全体验换纸面吞吐。</p>\n<p>第二类误用出现在 chunked prefill 部署里：仍用线性叠加式估算 TTFT，把预填算力项 <span class=\"sym\">\\(2N_{\\text{active}}S_{\\text{in}}/\\pi_{\\text{eff}}\\)</span> 与解码带宽项当成可加的两段。实际上 chunk 与解码步在同一 SM 上交替占用，预填的 MMA 占用会挤掉解码的带宽窗口，二者耦合使实测 TTFT 系统性偏离预测，且偏差随 <span class=\"sym\">\\(S_{\\text{in}}\\)</span> 增大而放大——仓库级上下文 <span class=\"sym\">\\(S_{\\text{in}}\\)</span> 可达 <span class=\"sym\">10^5</span>，此时预填 chunk 数多、交织次数多，耦合误差不可忽略。识别信号是：把 chunk 尺寸减半后 TTFT 不降反升，或 TPOT 随预填负载同步抖动，即说明两阶段争抢已成主导。工程上必须以实测校准替代公式直算，把 <span class=\"sym\">\\(π_{\\text{eff}}\\)</span> 视为随 chunk 配置变化的经验量而非常数。</p>\n<p>第三类误用方向相反：prefix 复用命中或 KV 分块驻留生效后，解码每步不再重读全 KV，<span class=\"sym\">\\(M_{\\text{KV}}(S)\\,B\\)</span> 项显著下降，但调参者仍沿用旧 <span class=\"sym\">\\(β_{\\text{eff}}\\)</span> 与旧曲线，把 <span class=\"sym\">B^{*}</span> 定得过低。此时 TPOT 对 <span class=\"sym\">B</span> 的敏感度已减弱，最优批应上移；继续用小批等于主动放弃摊薄固定开销的机会，吞吐被无谓牺牲而 p99 并无改善。识别方法是做一次 <span class=\"sym\">B</span> 扫描并观察 TPOT 斜率：若斜率明显低于无复用时的预期，就应重估 <span class=\"sym\">B^{*}</span>。三类误用共享一个根因——把模型当成静态公式而非随部署形态（到达过程、chunk 配置、复用命中率）漂移的近似，因此每次变更调度策略或缓存策略后都应重跑 p99 扫描，而不是复用上一版参数。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>按均值定批</td><td>均值/p99 比值随 B 扩大</td><td>突发下 SLO 违约</td></tr><tr><td>线性叠加估 TTFT</td><td>chunk 减半 TTFT 反升</td><td>预填阻塞解码、尾延迟抖动</td></tr><tr><td>复用命中后不调 B*</td><td>TPOT 对 B 斜率偏低</td><td>吞吐无谓损失</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>S_{\\text{in}}</td><td>输入（预填）token 数，仓库级上下文可达 10^5</td></tr><tr><td>T_{\\text{out}}</td><td>输出 token 数（代码补全通常 32–256）</td></tr><tr><td>\\pi_{\\text{eff}}</td><td>预填阶段有效算力（受 MMA 利用率与 attention 非线性影响）</td></tr><tr><td>\\beta_{\\text{eff}}</td><td>解码阶段有效带宽</td></tr><tr><td>\\tau_{\\text{queue}}</td><td>调度排队时延</td></tr><tr><td>B^{*}</td><td>使 p99 端到端时延最小的批大小</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-batch-latency-slo · 共 5 个片段</p>\n";break;}}})();
